const cart = db.prepare(\"SELECT * FROM carts WHERE customer_id = 'cust_001'\").all();
console.log('=== EMMA CHEN CART ===');
console.log(JSON.stringify(cart, null, 2));

// Check orders for cust_001
const orders = db.prepare(\"SELECT * FROM orders WHERE customer_id = 'cust_001' OR user_id = 'cust_001'\").all().catch?.(() => []);
try {
  const o1 = db.prepare(\"PRAGMA table_info(orders)\").all();
  console.log('=== ORDERS SCHEMA ===');
  console.log(JSON.stringify(o1, null, 2));
  const o2 = db.prepare(\"SELECT * FROM orders LIMIT 3\").all();
  console.log('=== SAMPLE ORDERS ===');
  console.log(JSON.stringify(o2, null, 2));
} catch(e) { console.log(e.message); }

// Support tickets
const st = db.prepare(\"PRAGMA table_info(support_tickets)\").all().catch?.(() => null);
try { console.log(db.prepare(\"SELECT name FROM sqlite_master WHERE name LIKE '%support%' OR name LIKE '%ticket%'\").all()); } catch(e) {}

// Check warranties for cust_001  
try {
  const w = db.prepare(\"SELECT * FROM warranties WHERE customer_id = 'cust_001'\").all();
  console.log('=== EMMA CHEN WARRANTIES ===');
  console.log(JSON.stringify(w, null, 2));
} catch(e) { console.log('warranties:', e.message); }

// Check order_items / payments / fulfillments for cust_001
try {
  const oi = db.prepare(\"SELECT * FROM order_items WHERE customer_id = 'cust_001'\").all();
  console.log('=== EMMA CHEN ORDER ITEMS ===');
  console.log(JSON.stringify(oi, null, 2));
} catch(e) {}
try {
  const cols = db.prepare('PRAGMA table_info(orders)').all().map(c => c.name);
  console.log('ORDER COLUMNS:', cols);
  let q = cols.includes('customer_id') ? 'customer_id' : 'user_id';
  const ords = db.prepare('SELECT * FROM orders WHERE ' + q + \" = 'cust_001'\").all();
  console.log('=== EMMA CHEN ORDERS ===');
  console.log(JSON.stringify(ords, null, 2));
} catch(e) { console.log('orders query:', e.message); }
