node -e "
const { DatabaseSync } = require('node:sqlite');
const db = new DatabaseSync('/workspace/world.db');
// Check for support-ticket related data in CSV
// Also check all tables for cust_001 references
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
for (const t of tables) {
  try {
    const cols = db.prepare('PRAGMA table_info(' + t.name + ')').all().map(c => c.name);
    for (const col of cols) {
      if (['customer_id','user_id'].includes(col)) {
        const rows = db.prepare('SELECT * FROM ' + t.name + ' WHERE ' + col + \" = 'cust_001'\").all();
        if (rows.length > 0) {
          console.log('=== ' + t.name + ' (' + col + ') ===');
          console.log(JSON.stringify(rows, null, 2));
        }
      }
    }
  } catch(e) {}
}
"

